Translate("frFR", "ruins-of-lordaeron", {
	title = "Ruines de Lordaeron",
	sections = {
		{
			title = "Résumé",
			text = [=[Au-dessus d'{link:undercity}Undercity{/link} s'étendent les rues brisées de la capitale de {link:lordaeron}Lordaeron{/link}. Les {link:forsaken}Réprouvés{/link} tiennent la cour devant leurs portes, mais au-delà, une grande partie de la vieille cité est encore aux mains du {link:scourge}Fléau{/link}. Des morts sans esprit errent dans les ruelles, de grandes araignées nichent dans les ruines, et des abominations cousues à partir des morts gardent les places. Depuis peu, un brouillard impie rampe sur les rues et sur le vieux cimetière. Les Réprouvés sont montés reprendre leur cité.]=],
		},
		{
			title = "Origines",
			text = [=[Ce fut la capitale de {link:lordaeron}Lordaeron{/link} jusqu'au jour où le prince {link:arthas-menethil}Arthas Menethil{/link} rentra chez lui et assassina son père. Le {link:scourge}Fléau{/link} mit la cité à sac et massacra ses habitants, et ceux qui tombèrent se relevèrent pour servir le roi-liche. Lorsque les {link:forsaken}Réprouvés{/link} se libérèrent, ils revendiquèrent les ruines et descendirent sous terre pour bâtir {link:undercity}Undercity{/link}. Ils n'avaient pas la force de nettoyer toute la cité en ruine au-dessus d'eux. Il y a peu, la nécropole {red:naxxramas}Naxxramas{/red} marcha contre la cité, et les combats firent rage dans ces mêmes rues. Ce que le Fléau laissa derrière lui n'a jamais été déblayé.]=],
		},
		{
			title = "Aujourd'hui",
			text = [=[Les {link:forsaken}Réprouvés{/link} se battent pour leurs anciennes rues, une place après l'autre. Ils perdent des soldats qu'ils ne peuvent pas remplacer, car la chair en décomposition ne guérit pas. Les gardes de la Mort ont appris que le brouillard est l'œuvre d'un nécromancien nommé {link:rath-mael}Rath'mael{/link}, une nouvelle puissance dans les rangs du {link:scourge}Fléau{/link}. Il semble préparer une autre attaque. Les apothicaires d'{link:undercity}Undercity{/link} veulent des échantillons des bêtes venimeuses des ruines, et les paladins des Réprouvés veulent les membres des morts, afin que leur peuple puisse être réparé.]=],
		},
		{
			title = "Dans les ruines",
			text = [=[• {b}King's Alley.{/b} Près de l'entrée, là où une grande araignée chasse avec sa couvée.
• {b}Market Street.{/b} Une place ouverte de la vieille cité, où les morts se rassemblent par vagues.
• {b}{link:lordaeron-graveyard}Lordaeron Graveyard{/link}.{/b} Le lieu de sépulture de la capitale, désormais enveloppé de brouillard.
• {b}Lordamere Overlook.{/b} Au cœur des ruines, là où {link:rath-mael}Rath'mael{/link} pratique sa magie.]=],
		},
		{
			title = "Reliques des morts",
			text = [=[Les ruines sont pleines de ce que les vivants ont laissé derrière eux. Des insignes de soldats gisent dans les décombres, attendant toujours leurs proches. Des blasons de l'ancien royaume apparaissent parmi les pierres, et les {link:forsaken}Réprouvés{/link} comme les habitants de {link:stormwind-city}Stormwind{/link} les veulent pour leur histoire. Dans le cimetière repose la dernière lettre d'un Réprouvé nommé Edward Heartweaver. Il venait ici chaque semaine chercher le corps de son fils, perdu quand {link:arthas-menethil}Arthas{/link} rasa la cité. Il ne revint pas. Son fils, on l'apprit plus tard, avait survécu. Il fut emmené dans un orphelinat de Stormwind, et il a depuis été adopté par une femme du {link:duskwood}Bois de la Pénombre{/link}.]=],
		},
		{
			title = "Ceux qui demeurent ici",
			text = [=[L'araignée {link:witherfang}Witherfang{/link}, l'abomination appelée {link:the-baron}le Baron{/link}, l'Abandonné, la bête {link:viktor-the-vile}Viktor le Vil{/link}, la brute {link:bjork}Bjork{/link} et le nécromancien {link:rath-mael}Rath'mael{/link} hantent tous les ruines. Le fantôme d'un capitaine de {link:lordaeron}Lordaeron{/link} est parfois aperçu parmi eux. Un soldat de l'{link:alliance}Alliance{/link} nommé le capitaine Truman tient toujours son poste dans les ruines, attendant un maître qui s'est jeté dans la mêlée il y a quelque temps et n'est pas revenu.]=],
		},
	},
})

Translate("frFR", "lordaeron-graveyard", {
	title = "Lordaeron Graveyard",
	sections = {
		{
			title = "Résumé",
			text = [=[Le Lordaeron Graveyard était le lieu de sépulture de la capitale. Aujourd'hui, les morts de la cité en ruine errent parmi ses pierres brisées. Le brouillard qui les cache est ici plus épais qu'ailleurs, et les vivants comme les {link:forsaken}Réprouvés{/link} n'y entrent qu'avec prudence. Un brouillard impie recouvre le cimetière, invoqué par le nécromancien {link:rath-mael}Rath'mael{/link}. Certains Réprouvés viennent encore ici chercher ceux qu'ils ont perdus, fouillant les pierres en quête de noms qu'ils connaissaient de leur vivant. Tous ne reviennent pas.]=],
		},
	},
})

Translate("frFR", "witherfang", {
	title = "Witherfang",
	subtitle = "Chasseresse de King's Alley",
	found = "Les ruelles près de l'entrée des ruines",
	hint = [=[Affrontez la grande araignée qui chasse avec sa couvée près de l'entrée des ruines.]=],
	allegiance = "Bêtes des ruines",
	sections = {
		{
			title = "Résumé",
			text = [=[Witherfang est une grande araignée qui chasse dans les ruelles de la capitale en ruine. Elle ne chasse jamais seule. Un essaim de ses petits la suit à travers les rues, et tout ce qu'elle mord est empoisonné. Les apothicaires d'{link:undercity}Undercity{/link} ont entendu dire que son venin peut ronger même la chair des morts-vivants. Cette rumeur effraie la plupart des {link:forsaken}Réprouvés{/link}. Elle ravit les apothicaires, qui préfèrent étudier un tel poison plutôt que le craindre.]=],
		},
		{
			title = "Importance",
			text = [=[Theodore Griffs, de l'Apothecarium, veut un échantillon de son poison, afin d'en percer les secrets pour la {link:royal-apothecary-society}Royal Apothecary Society{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit d'où vient Witherfang, ni depuis combien de temps elle chasse dans les ruines.]=],
		},
	},
	mentions = {
		{ text = "La nouvelle peste" },
	},
})

Translate("frFR", "the-baron", {
	title = "Le Baron",
	subtitle = "L'abomination à la tête d'emprunt",
	found = "Au bout d'un couloir, au sud-est des ruines",
	hint = [=[Affrontez la grande abomination qui garde les salles du sud-est des ruines.]=],
	allegiance = "Fléau",
	aliases = { "le Baron" },
	sections = {
		{
			title = "Résumé",
			text = [=[Le Baron est une énorme abomination qui garde une salle de la cité en ruine. Il frappe de grands coups tranchants et projette ses ennemis au loin. Sa tête a été arrachée puis recousue tant de fois qu'elle tient à peine. Le maître apothicaire {link:master-apothecary-faranell}Faranell{/link} connaît cette tête. Elle appartenait autrefois à un grand maréchal de l'{link:alliance}Alliance{/link}, un homme que {link:sylvanas-windrunner}la Dame noire{/link} tua de sa propre main.]=],
		},
		{
			title = "Importance",
			text = [=[Dans la mort, le grand maréchal est devenu un monstre dans les ruines du royaume qu'il était jadis venu sauver. Les {link:forsaken}Réprouvés{/link} ont des projets pour sa tête. Un capitaine de l'{link:alliance}Alliance{/link}, qui attend son maître dans les ruines, en a aussi.]=],
		},
	},
	mentions = {
		{ text = "Créatures abominables" },
		{ text = "Tourment sans fin" },
		{ text = "Tourment sans fin" },
	},
	bonds = {
		{ id = "master-apothecary-faranell", name = "Maître apothicaire Faranell", note = "connaît sa tête" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "a tué l'homme qu'il était" },
	},
})

Translate("frFR", "the-abandoned", {
	title = "L'Abandonné",
	subtitle = "Le Froid de Market Street",
	found = "Market Street, dans les ruines",
	hint = [=[Affrontez celui qui vient après les vagues de morts dans Market Street.]=],
	allegiance = "Fléau",
	sections = {
		{
			title = "Résumé",
			text = [=[L'Abandonné est un lanceur de sorts mort-vivant qui hante une ancienne place de la capitale en ruine. Il ne vient pas tout de suite. D'abord, les morts se rassemblent par vagues autour d'une statue, et ce n'est qu'une fois qu'ils sont tombés qu'il apparaît. Il s'enveloppe de givre, emprisonne ses ennemis dans la glace et draine leur vie pour nourrir la sienne. Il porte un sceptre que les {link:forsaken}Réprouvés{/link} convoitent.]=],
		},
		{
			title = "Importance",
			text = [=[L'Abandonné est l'une des puissances qui tiennent les ruines contre les {link:forsaken}Réprouvés{/link}.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit qui était l'Abandonné de son vivant, ni qui l'a abandonné. Son nom est tout ce que l'on sait.]=],
		},
	},
})

Translate("frFR", "viktor-the-vile", {
	title = "Viktor le Vil",
	subtitle = "La bête du foyer",
	found = "Caché dans les ruines, près d'un vieux foyer",
	hint = [=[Rallumez la flamme oubliée dans les ruines et voyez ce qui répond.]=],
	allegiance = "Bêtes des ruines",
	aliases = { "Viktor" },
	sections = {
		{
			title = "Résumé",
			text = [=[Viktor le Vil est une bête qui se cache quelque part dans les ruines de la capitale, là où peu penseraient à regarder. Il ne sort pas de lui-même. On dit que si l'on rallume le vieux foyer d'une maison en ruine, les morts arrivent par vagues successives, et qu'une fois celles-ci épuisées, Viktor vient en dernier. Il frappe fort et ne se lasse pas vite, et ceux qui le réveillent ont intérêt à être prêts avant d'allumer le feu.]=],
		},
		{
			title = "Importance",
			text = [=[Viktor est le secret des ruines. Beaucoup de ceux qui traversent la capitale ne le rencontrent jamais.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit quelle sorte de bête est Viktor, ni qui lui a donné son nom.]=],
		},
	},
})

Translate("frFR", "bjork", {
	title = "Bjork",
	subtitle = "La brute des ruines",
	found = "Les ruines du nord-ouest",
	hint = [=[Affrontez la brute morte-vivante qui arpente les ruines du nord-ouest.]=],
	allegiance = "Fléau",
	sections = {
		{
			title = "Résumé",
			text = [=[Bjork est une brute morte-vivante qui arpente les rues du nord-ouest de la capitale en ruine. Il porte de lourds coups qui repoussent même les guerriers en armure, et quand on retourne des sorts contre lui, il dresse une carapace de magie sombre qui les détourne. Les {link:forsaken}Réprouvés{/link} qui le combattent apprennent à attendre que la carapace se dissipe, et à garder un mur solide dans leur dos.]=],
		},
		{
			title = "Importance",
			text = [=[Bjork est l'un des gardiens que le {link:scourge}Fléau{/link} a laissés dans les ruines après la chute de la cité.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit qui ou ce qu'était Bjork avant de venir dans les ruines. Même son nom n'est pas expliqué.]=],
		},
	},
})

Translate("frFR", "rath-mael", {
	title = "Rath'mael",
	subtitle = "Nécromancien du Fléau",
	found = "Le Lordamere Overlook, au cœur des ruines",
	hint = [=[Cherchez le nécromancien dont le brouillard recouvre la cité en ruine.]=],
	allegiance = "Fléau",
	sections = {
		{
			title = "Résumé",
			text = [=[Rath'mael est un nécromancien du {link:scourge}Fléau{/link}, une nouvelle puissance dans ses rangs. Depuis le Lordamere Overlook, au cœur des ruines de la capitale, il a jeté un brouillard impie sur les rues et le cimetière. Le brouillard cache les morts aux yeux des {link:forsaken}Réprouvés{/link}. Ceux qui l'atteignent affrontent un maître du feu autant que de la mort. Il fait tomber la flamme du ciel et brûle tous ceux qui se tiennent près de lui.]=],
		},
		{
			title = "Importance",
			text = [=[Les {link:forsaken}Réprouvés{/link} croient que Rath'mael prépare une autre attaque. Ils ne peuvent pas se permettre d'attendre de voir où elle frappera. Les gardes de la Mort de {link:brill}Brill{/link} veulent le chasser de leurs terres.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne dit qui était Rath'mael de son vivant, ni qui l'a envoyé dans les ruines.]=],
		},
	},
	mentions = {
		{ text = "Le courroux de Rath'mael" },
	},
	bonds = {
		{ id = "deathguard-kristof", name = "Garde de la Mort Kristof", note = "veut sa mort" },
	},
})

Translate("frFR", "lordaeron-captain", {
	title = "Capitaine de Lordaeron",
	subtitle = "Un capitaine du royaume déchu",
	found = "Rarement vu dans les ruines",
	hint = [=[Guettez le capitaine déchu que l'on voit rarement dans les ruines.]=],
	allegiance = "Lordaeron (déchu)",
	sections = {
		{
			title = "Résumé",
			text = [=[Parfois, dans les ruines de la capitale, les morts de l'armée de {link:lordaeron}Lordaeron{/link} se tiennent encore à leur poste. L'un d'eux est un capitaine de l'ancien royaume. On le voit rarement, et nul ne sait quand il apparaîtra. Quel que soit le serment qui le liait jadis à la cité, il se tient toujours parmi ses ruines, bien après la disparition du royaume qu'il servait.]=],
		},
		{
			title = "Importance",
			text = [=[Le capitaine rappelle que les soldats de {link:lordaeron}Lordaeron{/link} sont tombés en défendant cette cité. Certains d'entre eux ne se sont pas encore arrêtés.]=],
		},
		{
			title = "Non consigné",
			text = [=[Aucune chronique ne donne son nom, sa compagnie, ni ne dit s'il sait ce qu'est devenue sa cité.]=],
		},
	},
})
